const TEMPLATE_SRC = 'data:image/jpeg;base64,';

const fieldsList = [
  { id: 'manufacturedBy', label: 'Manufactured By', placeholder: 'e.g. ABC Company' },
  { id: 'countryOrigin', label: 'Country of Origin', placeholder: 'e.g. India' },
  { id: 'description', label: 'Description of Goods', placeholder: 'e.g. Protein Powder' },
  { id: 'netWeight', label: 'Net Weight', placeholder: 'e.g. 1 KG' },
  { id: 'quantity', label: 'Quantity', placeholder: 'e.g. 1' },
  { id: 'batchNo', label: 'Batch No.', placeholder: 'e.g. ABC123' },
  { id: 'manufacturingDate', label: 'Manufacturing Date', placeholder: 'e.g. 01/08/2026' },
  { id: 'expiryDate', label: 'Expiry Date', placeholder: 'e.g. 01/08/2028' },
  { id: 'monthOfImport', label: 'Month of Import', placeholder: 'e.g. August 2026' },
  { id: 'mrp', label: 'MRP', placeholder: 'e.g. 2999' }
];

// Global text styling
const textStyle = {
  font: "500 16px Inter, sans-serif",
  color: "#1e1e1e"
};

let canvas, ctx;
let templateImage = new Image();
let inputs = {};

document.addEventListener('DOMContentLoaded', () => {
  initUI();
  initCalibration();
  initCanvas();
  loadTemplate();
});

function initUI() {
  const container = document.getElementById('inputs-container');
  
  fieldsList.forEach(field => {
    const group = document.createElement('div');
    group.className = 'input-group';
    
    const label = document.createElement('label');
    label.textContent = field.label;
    label.htmlFor = field.id;
    
    const input = document.createElement('input');
    input.type = 'text';
    input.id = field.id;
    input.placeholder = field.placeholder;
    // value is empty by default so the user doesn't have to backspace
    
    input.addEventListener('input', renderCanvas);
    inputs[field.id] = input;
    
    group.appendChild(label);
    group.appendChild(input);
    container.appendChild(group);
  });

  document.getElementById('btn-download-png').addEventListener('click', downloadPNG);
  document.getElementById('btn-download-pdf').addEventListener('click', downloadPDF);
  document.getElementById('show-debug').addEventListener('change', renderCanvas);
}

function initCalibration() {
  const ids = ['calib-x', 'calib-y', 'calib-spacing', 'calib-mrp-x', 'calib-mrp-y'];
  ids.forEach(id => {
    const el = document.getElementById(id);
    if (el) {
      el.addEventListener('input', (e) => {
        document.getElementById(id.replace('calib-', 'val-')).textContent = e.target.value;
        renderCanvas();
      });
    }
  });
  document.getElementById('calib-mask').addEventListener('change', renderCanvas);
}

function initCanvas() {
  canvas = document.getElementById('label-canvas');
  ctx = canvas.getContext('2d');
}

function loadTemplate() {
  templateImage.onload = () => {
    canvas.width = templateImage.width;
    canvas.height = templateImage.height;
    renderCanvas();
  };
  templateImage.src = TEMPLATE_SRC;
}

function renderCanvas() {
  if (!templateImage.complete || templateImage.naturalWidth === 0) return;

  ctx.clearRect(0, 0, canvas.width, canvas.height);
  ctx.drawImage(templateImage, 0, 0);

  const showDebug = document.getElementById('show-debug').checked;
  const startX = parseInt(document.getElementById('calib-x').value, 10);
  const startY = parseInt(document.getElementById('calib-y').value, 10);
  const spacing = parseInt(document.getElementById('calib-spacing').value, 10);
  const mrpX = parseInt(document.getElementById('calib-mrp-x').value, 10);
  const mrpY = parseInt(document.getElementById('calib-mrp-y').value, 10);
  const maskStyle = document.getElementById('calib-mask').value;

  fieldsList.forEach((field, index) => {
    const val = inputs[field.id].value;
    
    let posX = startX;
    let posY = startY + (index * spacing);
    let maskWidth = 220; 
    
    if (field.id === 'mrp') {
      posX = mrpX;
      posY = mrpY;
      maskWidth = 90; // Shorter mask for MRP
    }

    if (maskStyle !== 'none') {
      applyMask(posX, posY, maskWidth, showDebug, maskStyle);
    }

    ctx.font = textStyle.font;
    ctx.fillStyle = textStyle.color;
    ctx.textAlign = 'left';
    ctx.textBaseline = 'alphabetic';
    
    if (val.trim() !== '') {
      ctx.fillText(val, posX, posY);
    }
    
    if (showDebug) {
      ctx.fillStyle = 'red';
      ctx.beginPath();
      ctx.arc(posX, posY, 4, 0, Math.PI * 2);
      ctx.fill();
    }
  });
}

function applyMask(x, y, w, showDebug, style) {
  const maskX = x - 5;
  const maskY = y - 18;
  const maskH = 22;

  if (style === 'solid') {
    // Solid color mask to cleanly wipe the old text (light gray to match background)
    ctx.fillStyle = '#f0f1f4';
    ctx.fillRect(maskX, maskY, w, maskH);
  } else if (style === 'stretch') {
    // Sample a 10px slice to the left and stretch it
    const sourceX = maskX - 15;
    const sourceY = maskY;
    ctx.drawImage(
      templateImage, 
      sourceX, sourceY, 10, maskH, 
      maskX, maskY, w, maskH 
    );
  }

  if (showDebug) {
    ctx.lineWidth = 1;
    ctx.strokeStyle = 'rgba(0, 0, 255, 0.9)';
    ctx.strokeRect(maskX, maskY, w, maskH);
  }
}

function downloadPNG() {
  const wasDebug = document.getElementById('show-debug').checked;
  if (wasDebug) {
    document.getElementById('show-debug').checked = false;
    renderCanvas();
  }
  const link = document.createElement('a');
  link.download = 'label_updated.png';
  link.href = canvas.toDataURL('image/png');
  link.click();
  if (wasDebug) {
    document.getElementById('show-debug').checked = true;
    renderCanvas();
  }
}

function downloadPDF() {
  const wasDebug = document.getElementById('show-debug').checked;
  if (wasDebug) {
    document.getElementById('show-debug').checked = false;
    renderCanvas();
  }
  const imgData = canvas.toDataURL('image/jpeg', 0.95);
  const { jsPDF } = window.jspdf;
  const orientation = canvas.width > canvas.height ? 'l' : 'p';
  const pdf = new jsPDF({
    orientation: orientation,
    unit: 'px',
    format: [canvas.width, canvas.height]
  });
  pdf.addImage(imgData, 'JPEG', 0, 0, canvas.width, canvas.height);
  pdf.save('label_updated.pdf');
  if (wasDebug) {
    document.getElementById('show-debug').checked = true;
    renderCanvas();
  }
}
